    Bug 1981696 - some adjustments after bug 1975367. r=kaie


    onSendOpenPGP() was meant to never throw, as implied by the logging in the catch, which would not necssarily be reached, since we are returning the promise.
    We must await the promise instead. Then the extra try/catch is not needed

    Differential Revision: https://phabricator.services.mozilla.com/D260271

diff --git a/mail/components/compose/content/MsgComposeCommands.js b/mail/components/compose/content/MsgComposeCommands.js
index ad56bc42d4b..cce05532bea 100644
--- a/mail/components/compose/content/MsgComposeCommands.js
+++ b/mail/components/compose/content/MsgComposeCommands.js
@@ -6424,11 +6424,7 @@ async function CompleteGenericSendMessage(msgType) {
     }

     if (gSelectedTechnologyIsPGP) {
-      let pgpSuccess = false;
-      try {
-        pgpSuccess = await Enigmail.msg.onSendOpenPGP(msgType);
-      } catch (ex) {}
-      if (!pgpSuccess) {
+      if (!(await Enigmail.msg.onSendOpenPGP(msgType))) {
         Enigmail.msg.resetUpdatedFields();
         return;
       }
diff --git a/mail/extensions/openpgp/content/ui/enigmailMsgComposeOverlay.js b/mail/extensions/openpgp/content/ui/enigmailMsgComposeOverlay.js
index 4083a59efe9..acde515c718 100644
--- a/mail/extensions/openpgp/content/ui/enigmailMsgComposeOverlay.js
+++ b/mail/extensions/openpgp/content/ui/enigmailMsgComposeOverlay.js
@@ -1548,7 +1548,7 @@ Enigmail.msg = {
       return true;
     }
     try {
-      return this.prepareSendMsg(mode);
+      return await this.prepareSendMsg(mode);
     } catch (e) {
       console.error(`Prepare send msg FAILED: ${e.message}`, e);
       return false;
